do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-062","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"w0","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL1932332W"},"before":null,"after":{"title":"The status civilization","author_id":3477,"first_publish_year":1960,"open_library_id":"OL1932332W","cover_id":12144682,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL1932332W"}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL9086943M"},"before":null,"after":{"work_id":"@w0","open_library_edition_id":"OL9086943M","isbn_13":"9789022990056","isbn_10":null,"title":"De statusplaneet","language":"dut","publisher":"Bruna"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":"@w0","language":"nl"},"before":null,"after":{"work_id":"@w0","language":"nl","bound_author_id":3477,"text":"Will Barrent ontwaakt zonder herinneringen en wordt als veroordeelde op de planeet Omega afgezet. Daar gelden regels die hij nauwelijks kan begrijpen: geweld kan aanzien opleveren en een wettelijk recht biedt weinig bescherming tegen de dood. Om te overleven moet hij leren hoe deze samenleving werkt. Tegelijk zoekt hij naar zijn verleden en naar de reden van zijn veroordeling. De confrontatie met Omega roept ook vragen op over de aarde die hem heeft verbannen en over de macht van gehoorzaamheid.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.simonandschuster.com/books/The-Status-Civilization/Robert-Sheckley/9781627930567","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p853216908"],"reference":"new-work-dossier-readings-062.json#203","checked_at":"2026-11-03T12:32:10.025Z","note":"Exact KB p853216908 is DutchprintISBN9789022990056, title De statusplaneet and publicationlabel Utrecht etc.:Bruna.1971. Raw OL title appends an erroneous Bruno series and p